package com.sodi.metareports.audit; import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import java.sql.Types; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service;
@Service public class JdbcAuditService implements AuditService { private final JdbcTemplate jdbc; private final ObjectMapper json; public JdbcAuditService(JdbcTemplate j,ObjectMapper o){jdbc=j;json=o;}
 public void record(String a,String t,String id,String d,Object old,Object current){String actor=SecurityContextHolder.getContext().getAuthentication()==null?null:SecurityContextHolder.getContext().getAuthentication().getName();jdbc.update("insert into audit_log(actor_user_id,action,entity_type,entity_id,description,previous_data,new_data) select u.id,?,?,?,?,?::jsonb,?::jsonb from (select ?::varchar as username) x left join app_user u on u.username=x.username",a,t,id,d,toJson(old),toJson(current),actor);}
 private String toJson(Object v){if(v==null)return null;try{return json.writeValueAsString(v);}catch(JsonProcessingException e){return "{\"serializationError\":true}";}}
}
